import hashlib
import json
import time
import uuid
from enum import Enum


class Risk(Enum):
    READ = 1
    WRITE_REVERSIBLE = 2
    WRITE_IRREVERSIBLE = 3


def describe(tool, args):
    """The approval text: generated by code from the real parameters, never written by the model."""
    return f"{tool}(" + ", ".join(f"{k}={v!r}" for k, v in sorted(args.items())) + ")"


class Executor:
    def __init__(self, tools, risk, may_use, clock=time.time, ttl=600):
        self.tools, self.risk, self.may_use, self.clock, self.ttl = tools, risk, may_use, clock, ttl
        self.pending, self.audit = {}, []

    def _fingerprint(self, user, tool, args):
        return hashlib.sha256(json.dumps([user, tool, args], sort_keys=True).encode()).hexdigest()

    def execute(self, user, tool, args):
        """Returns the tool_result text the model sees."""
        risk = self.risk.get(tool, Risk.WRITE_IRREVERSIBLE)          # unknown tool = most dangerous
        if not self.may_use(user, tool):
            self.audit.append((user, tool, "DENIED"))
            return f"You are not allowed to use {tool}."
        if risk is Risk.WRITE_IRREVERSIBLE:
            pid = uuid.uuid4().hex[:8]
            self.pending[pid] = {"fp": self._fingerprint(user, tool, args), "user": user, "tool": tool,
                                 "args": args, "summary": describe(tool, args), "expires": self.clock() + self.ttl}
            self.audit.append((user, tool, "PENDING"))
            return f"Needs the user's approval; NOT performed. Approval id {pid}."
        self.audit.append((user, tool, "EXECUTED"))
        return self.tools[tool](user=user, **args)

    def approve(self, pid, user, tool, args):
        """Called by the UI when the human clicks Approve. Bound to user, tool and exact args; single use."""
        p = self.pending.pop(pid, None)                              # pop: single use
        if p is None or self.clock() > p["expires"]:
            return "approval missing or expired"
        if p["fp"] != self._fingerprint(user, tool, args):
            return "approval does not match this action"
        self.audit.append((user, tool, "EXECUTED_AFTER_APPROVAL"))
        return self.tools[tool](user=user, **args)
